CREATE TABLE ZTOKENMETAINFORMATION (
    Z_PK INTEGER PRIMARY KEY, ZFILE INTEGER, ZTOKEN INTEGER, ZANCHOR VARCHAR
);
CREATE TABLE ZFILEPATH (Z_PK INTEGER PRIMARY KEY, ZPATH VARCHAR);
